#[cfg(test)]
mod tests {
    use super::*;

    fn s(v: &[&str]) -> Vec<String> {
        v.iter().map(|x| x.to_string()).collect()
    }

    #[test]
    fn example() {
        let tasks = ["cook", "eat", "shop", "wash"];
        let deps = [("shop", "cook"), ("cook", "eat"), ("wash", "cook")];
        assert_eq!(topo_order(&tasks, &deps), Ok(s(&["shop", "wash", "cook", "eat"])));
    }

    #[test]
    fn no_deps_sorted() {
        assert_eq!(topo_order(&["c", "a", "b"], &[]), Ok(s(&["a", "b", "c"])));
        assert_eq!(topo_order(&[], &[]), Ok(vec![]));
    }

    #[test]
    fn lexicographic_choice_among_ready() {
        let tasks = ["a", "b", "c", "d"];
        let deps = [("d", "a"), ("c", "b"), ("c", "b")];
        assert_eq!(topo_order(&tasks, &deps), Ok(s(&["c", "b", "d", "a"])));
    }

    #[test]
    fn unknown_task() {
        let r = topo_order(&["a", "b"], &[("a", "b"), ("b", "zz"), ("yy", "a")]);
        assert_eq!(r, Err(TopoError::UnknownTask("zz".to_string())));
    }

    #[test]
    fn cycles() {
        let tasks = ["a", "b", "c", "d", "e"];
        let deps = [("a", "b"), ("b", "c"), ("c", "b"), ("c", "d")];
        assert_eq!(topo_order(&tasks, &deps), Err(TopoError::Cycle(s(&["b", "c", "d"]))));
        assert_eq!(topo_order(&["x"], &[("x", "x")]), Err(TopoError::Cycle(s(&["x"]))));
    }

    #[test]
    fn long_chain() {
        let names: Vec<String> = (0..1000).map(|i| format!("t{:04}", i)).collect();
        let tasks: Vec<&str> = names.iter().rev().map(|x| x.as_str()).collect();
        let deps: Vec<(&str, &str)> = names.windows(2).map(|w| (w[0].as_str(), w[1].as_str())).collect();
        assert_eq!(topo_order(&tasks, &deps), Ok(names.clone()));
    }
}
